def DLe {ι : Type} (f : PartialBool ι) (budget : ℕ) : Prop :=
  ∃ tree : QueryTree ι,
    tree.depth ≤ budget ∧ ∀ x b, f x = some b → tree.eval x = b

noncomputable def FixedSim.unitary {V : State (Fin N) w →ₗᵢ[ℂ] State (Fin N) w}
    {A : AdaptiveProgram (Fin N) w} {T : ℕ} (s : FixedSim A T) :
    FixedSim (.unitary V A) T

theorem constructionPartial_reconstruct {ι : Type} (f : PartialBool ι) :
    constructionPartial {x | promised f x}
      (fun x => Classical.choose x.property) = f

theorem construction_exponent_set_wellDefined :
    ({α : ℝ | UniversalPower α}).Nonempty ∧
      BddBelow {α : ℝ | UniversalPower α}

theorem construction_promised_iff {ι : Type}
    (D : Set (BitInput ι)) (f : D → Bool) (x : BitInput ι) :
    promised (constructionPartial D f) x ↔ x ∈ D

def RLe {ι : Type} (f : PartialBool ι) (budget : ℕ) : Prop :=
  ∃ A : RandomizedProgram ι,
    A.depth ≤ budget ∧ ∀ x b, f x = some b → (2 / 3 : ℝ) ≤ A.success x b

noncomputable def RandomizedProgram.success {ι : Type}
    (A : RandomizedProgram ι) (x : BitInput ι) (b : Bool) : ℝ :=
  ∑ j, if (A.tree j).eval x = b then A.weight j else 0

noncomputable def project {ι : Type} [Fintype ι] {w : ℕ}
    (S : Finset (Basis ι w)) (ψ : State ι w) : State ι w :=
  WithLp.toLp 2 fun p => if p ∈ S then ψ.ofLp p else 0
